 static int usbtmc488_ioctl_trigger(struct usbtmc_file_data *file_data)
 {
 	struct usbtmc_device_data *data = file_data->data;
 	int retval;
 	u8 *buffer;
 	int actual;

 	buffer = kzalloc(USBTMC_HEADER_SIZE, GFP_KERNEL);
 	if (!buffer)
 		return -ENOMEM;

 	buffer[0] = 128;
 	buffer[1] = data->bTag;
 	buffer[2] = ~data->bTag;

-	retval = usb_bulk_msg(data->usb_dev,
+	retval = usb_bulk_msg_killable(data->usb_dev,
 			      usb_sndbulkpipe(data->usb_dev,
 					      data->bulk_out),
 			      buffer, USBTMC_HEADER_SIZE,
 			      &actual, file_data->timeout);

 	/* Store bTag (in case we need to abort) */
 	data->bTag_last_write = data->bTag;

 	/* Increment bTag -- and increment again if zero */
 	data->bTag++;
 	if (!data->bTag)
 		data->bTag++;

 	kfree(buffer);
 	if (retval < 0) {
 		dev_err(&data->intf->dev, "%s returned %d\n",
 			__func__, retval);
 		return retval;
 	}

 	return 0;
 }

  */
 static int send_request_dev_dep_msg_in(struct usbtmc_file_data *file_data,
 				       u32 transfer_size)
 {
 	struct usbtmc_device_data *data = file_data->data;
 	int retval;
 	u8 *buffer;
 	int actual;

 	buffer = kmalloc(USBTMC_HEADER_SIZE, GFP_KERNEL);
 	if (!buffer)
 		return -ENOMEM;
 	/* Setup IO buffer for REQUEST_DEV_DEP_MSG_IN message
 	 * Refer to class specs for details
 	 */
 	buffer[0] = 2;
 	buffer[1] = data->bTag;
 	buffer[2] = ~data->bTag;
 	buffer[3] = 0; /* Reserved */
 	buffer[4] = transfer_size >> 0;
 	buffer[5] = transfer_size >> 8;
 	buffer[6] = transfer_size >> 16;
 	buffer[7] = transfer_size >> 24;
 	buffer[8] = file_data->term_char_enabled * 2;
 	/* Use term character? */
 	buffer[9] = file_data->term_char;
 	buffer[10] = 0; /* Reserved */
 	buffer[11] = 0; /* Reserved */

 	/* Send bulk URB */
-	retval = usb_bulk_msg(data->usb_dev,
+	retval = usb_bulk_msg_killable(data->usb_dev,
 			      usb_sndbulkpipe(data->usb_dev,
 					      data->bulk_out),
 			      buffer, USBTMC_HEADER_SIZE,
 			      &actual, file_data->timeout);

 	/* Store bTag (in case we need to abort) */
 	data->bTag_last_write = data->bTag;

 	/* Increment bTag -- and increment again if zero */
 	data->bTag++;
 	if (!data->bTag)
 		data->bTag++;

 	kfree(buffer);
 	if (retval < 0)
 		dev_err(&data->intf->dev, "%s returned %d\n",
 			__func__, retval);

 	return retval;
 }

 static ssize_t usbtmc_read(struct file *filp, char __user *buf,
 			   size_t count, loff_t *f_pos)
 {
 	struct usbtmc_file_data *file_data;
 	struct usbtmc_device_data *data;
 	struct device *dev;
 	const u32 bufsize = USBTMC_BUFSIZE;
 	u32 n_characters;
 	u8 *buffer;
 	int actual;
 	u32 done = 0;
 	u32 remaining;
 	int retval;

 	/* Get pointer to private data structure */
 	file_data = filp->private_data;
 	data = file_data->data;
 	dev = &data->intf->dev;

 	buffer = kmalloc(bufsize, GFP_KERNEL);
 	if (!buffer)
 		return -ENOMEM;

 	retval = mutex_lock_interruptible(&data->io_mutex);
 	if (retval < 0)
 		goto exit_nolock;

 	if (data->zombie) {
 		retval = -ENODEV;
 		goto exit;
 	}

 	if (count > INT_MAX)
 		count = INT_MAX;

 	dev_dbg(dev, "%s(count:%zu)\n", __func__, count);

 	retval = send_request_dev_dep_msg_in(file_data, count);

 	if (retval < 0) {
 		if (file_data->auto_abort)
 			usbtmc_ioctl_abort_bulk_out(data);
 		goto exit;
 	}

 	/* Loop until we have fetched everything we requested */
 	remaining = count;
 	actual = 0;

 	/* Send bulk URB */
-	retval = usb_bulk_msg(data->usb_dev,
+	retval = usb_bulk_msg_killable(data->usb_dev,
 			      usb_rcvbulkpipe(data->usb_dev,
 					      data->bulk_in),
 			      buffer, bufsize, &actual,
 			      file_data->timeout);

 	dev_dbg(dev, "%s: bulk_msg retval(%u), actual(%d)\n",
 		__func__, retval, actual);

 	/* Store bTag (in case we need to abort) */
 	data->bTag_last_read = data->bTag;

 	if (retval < 0) {
 		if (file_data->auto_abort)
 			usbtmc_ioctl_abort_bulk_in(data);
 		goto exit;
 	}

 	/* Sanity checks for the header */
 	if (actual < USBTMC_HEADER_SIZE) {
 		dev_err(dev, "Device sent too small first packet: %u < %u\n",
 			actual, USBTMC_HEADER_SIZE);
 		if (file_data->auto_abort)
 			usbtmc_ioctl_abort_bulk_in(data);
 		goto exit;
 	}

 	if (buffer[0] != 2) {
 		dev_err(dev, "Device sent reply with wrong MsgID: %u != 2\n",
 			buffer[0]);
 		if (file_data->auto_abort)
 			usbtmc_ioctl_abort_bulk_in(data);
 		goto exit;
 	}

 	if (buffer[1] != data->bTag_last_write) {
 		dev_err(dev, "Device sent reply with wrong bTag: %u != %u\n",
 		buffer[1], data->bTag_last_write);
 		if (file_data->auto_abort)
 			usbtmc_ioctl_abort_bulk_in(data);
 		goto exit;
 	}

 	/* How many characters did the instrument send? */
 	n_characters = buffer[4] +
 		       (buffer[5] << 8) +
 		       (buffer[6] << 16) +
 		       (buffer[7] << 24);

 	file_data->bmTransferAttributes = buffer[8];

 	dev_dbg(dev, "Bulk-IN header: N_characters(%u), bTransAttr(%u)\n",
 		n_characters, buffer[8]);

 	if (n_characters > remaining) {
 		dev_err(dev, "Device wants to return more data than requested: %u > %zu\n",
 			n_characters, count);
 		if (file_data->auto_abort)
 			usbtmc_ioctl_abort_bulk_in(data);
 		goto exit;
 	}

 	print_hex_dump_debug("usbtmc ", DUMP_PREFIX_NONE,
 			     16, 1, buffer, actual, true);

 	remaining = n_characters;

 	/* Remove the USBTMC header */
 	actual -= USBTMC_HEADER_SIZE;

 	/* Remove padding if it exists */
 	if (actual > remaining)
 		actual = remaining;

 	remaining -= actual;

 	/* Copy buffer to user space */
 	if (copy_to_user(buf, &buffer[USBTMC_HEADER_SIZE], actual)) {
 		/* There must have been an addressing problem */
 		retval = -EFAULT;
 		goto exit;
 	}

 	if ((actual + USBTMC_HEADER_SIZE) == bufsize) {
 		retval = usbtmc_generic_read(file_data, buf + actual,
 					     remaining,
 					     &done,
 					     USBTMC_FLAG_IGNORE_TRAILER);
 		if (retval < 0)
 			goto exit;
 	}
 	done += actual;

 	/* Update file position value */
 	*f_pos = *f_pos + done;
 	retval = done;

 exit:
 	mutex_unlock(&data->io_mutex);
 exit_nolock:
 	kfree(buffer);
 	return retval;
 }



